(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.035+t*0.15)*8+Math.cos((y+wy1)*0.025-t*0.18)*6;
  const wy2 = Math.cos((y+wy1)*0.03-t*0.12)*8+Math.sin((x+wx1)*0.028+t*0.22)*6;
  const wx3 = Math.sin((x+wx2)*0.05+t*0.08)*4;
  const wy3 = Math.cos((y+wy2)*0.045-t*0.1)*4;
  const sx = x+wx1+wx2+wx3, sy = y+wy1+wy2+wy3;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65)*40,0.11,2.1],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+1)*50,0.05,2.8],
    [200+Math.sin(t*0.25+6)*110,220+Math.cos(t*0.45+4)*70,0.13,1.3]
  ];
  let aS=0,iS=0,aS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.cos(d*f*1.3-t*sp*0.8+0.7);
  }
  const n=src.length,act=aS/n,inh=iS/n,act2=aS2/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin((sx+sy)*0.12+t*2.5)+Math.sin((sx-sy)*0.1-t*2))/2;
  const bg3=Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*0.5)*Math.cos(sy*0.07+Math.sin(sx*0.05-t)*2-t*0.4);
  const bg=bg1+bg2*0.4+bg3*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.08+ang*2-t*0.8)+Math.cos(dist*0.06-ang*5+t*1.0))*0.2;
  const n1=Math.sin(sx*0.17+sy*0.13+t*0.7)*Math.sin(sx*0.11-sy*0.19-t*0.5)*Math.cos(sx*0.07+sy*0.23+t*0.9);
  const n2=Math.sin((sx+sy)*0.09+t*1.3)*Math.sin((sx-sy*0.7)*0.11-t*0.8);
  const noise=(n1+n2)*0.3;
  const cross=act*act2*0.3;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2)*2.2);
  const r2=Math.tanh((r1*0.8+noise-Math.abs(inh)*0.5+cross)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const moire=Math.sin(dist*0.15)*Math.sin(dist*0.13+t*0.5)*Math.sin(ang*6+t*0.3)*0.2;
  const pulse=0.95+Math.sin(t*0.4)*0.05;
  const blend=(r2*0.5+cell*0.2+moire*0.15+noise*0.1)*pulse;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,48],[10,45,78],[15,90,108],[30,140,120],
    [65,170,110],[160,185,55],[210,160,40],[215,110,45],
    [190,65,55],[145,35,65],[85,20,60],[35,12,52],[5,10,48]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(r2*Math.PI)*0.2;
  const edge=Math.abs(r2)>0.7?1.15:(Math.abs(r2)<0.12?0.88:1.0);
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/420*0.25;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
